import { useState, useEffect } from 'react';
import axios from 'axios';

const RoomManager = () => {
  const [rooms, setRooms] = useState([]);
  const [number, setNumber] = useState('');
  const [hasProjector, setHasProjector] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [error, setError] = useState('');
  const [fieldErrors, setFieldErrors] = useState({});

  const fetchRooms = async () => {
    try {
      const res = await axios.get('/api/rooms');
      setRooms(res.data);
    } catch {
      setError('Ошибка загрузки аудиторий');
    }
  };

  useEffect(() => {
    fetchRooms();
  }, []);

  const resetForm = () => {
    setNumber('');
    setHasProjector(false);
    setEditingId(null);
    setError('');
    setFieldErrors({});
  };

  const validate = () => {
    const errors = {};
    if (!number.trim()) {
      errors.number = 'Номер обязателен';
    }
    setFieldErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    if (!validate()) return;

    try {
      if (editingId) {
        await axios.put(`/api/rooms/${editingId}`, { number: number.trim(), hasProjector });
      } else {
        await axios.post('/api/rooms', { number: number.trim(), hasProjector });
      }
      resetForm();
      fetchRooms();
    } catch (err) {
      setError(err.response?.data?.message || 'Ошибка');
    }
  };

  const handleEdit = (room) => {
    setEditingId(room.id);
    setNumber(room.number);
    setHasProjector(room.hasProjector);
    setFieldErrors({});
  };

  const handleDelete = async (id) => {
    if (window.confirm('Удалить аудиторию?')) {
      await axios.delete(`/api/rooms/${id}`);
      fetchRooms();
    }
  };

  return (
    <div className="room-manager">
      <h2>Аудитории</h2>
      {error && <div className="error-message">{error}</div>}
      <form onSubmit={handleSubmit} className="room-form">
        <div className="form-group">
          <input
            type="text"
            placeholder="Номер аудитории"
            value={number}
            onChange={(e) => {
              setNumber(e.target.value);
              if (fieldErrors.number) setFieldErrors(prev => ({ ...prev, number: undefined }));
            }}
            required
          />
          {fieldErrors.number && <span className="field-error">{fieldErrors.number}</span>}
        </div>

        <div className="form-group checkbox-group">
          <label>
            <input
              type="checkbox"
              checked={hasProjector}
              onChange={(e) => setHasProjector(e.target.checked)}
            />
            Проектор
          </label>
        </div>

        <div className="form-buttons">
          <button type="submit">{editingId ? 'Обновить' : 'Добавить'}</button>
          {editingId && <button type="button" onClick={resetForm}>Отмена</button>}
        </div>
      </form>

      <div style={{ overflowX: 'auto' }}>
        <table className="room-table">
          <thead>
            <tr>
              <th>ID</th>
              <th>Номер</th>
              <th>Проектор</th>
              <th>Действия</th>
            </tr>
          </thead>
          <tbody>
            {rooms.map(room => (
              <tr key={room.id}>
                <td>{room.id}</td>
                <td>{room.number}</td>
                <td>{room.hasProjector ? 'Да' : 'Нет'}</td>
                <td>
                  <button onClick={() => handleEdit(room)} title="Редактировать">✏️</button>
                  <button onClick={() => handleDelete(room.id)} title="Удалить">🗑️</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default RoomManager;
